(() => {
  // Native MathML remains selectable and scales with the page.
  const sub=(v,k)=>'<msub><mi>'+v+'</mi><mi>'+k+'</mi></msub>';
  const frac=(a,b)=>'<mfrac><mrow>'+a+'</mrow><mrow>'+b+'</mrow></mfrac>';
  const I=k=>sub('I',k),V=k=>sub('V',k),alpha=sub('α','F');
  window.bjtLessons=[
    {name:'结构与极性',title:'三个区，两个结',q:'切换 NPN 与 PNP，再分别高亮发射结和集电结。哪一端掺杂最重？平衡时能带在哪里弯曲？',
     controls:['width','ne','nc'],measure:'平衡能带与基区剖面',heading:'发射区、基区与集电区承担不同功能',
     eq:V('CE')+'<mo>=</mo>'+V('BE')+'<mo>−</mo>'+V('BC'),
     text:'E、B、C 分别接到发射区、基区和集电区。重掺杂发射区有利于向基区注入少子；较轻掺杂的集电区容纳反偏耗尽层。符号上的发射极箭头从 P 指向 N。用位置游标对照两处能带弯曲与截面。',
     limit:'热平衡、零外加电压。一维均匀掺杂突变同质结模型，假设杂质完全电离。电子能量以发射区导带为参考；重掺杂区的简并和带隙变窄未标定。'},
    {name:'注入与收集',title:'跟踪一次发射、输运与收集',q:'保持集电结反偏，升高发射结正向电压。多少电流由集电极收集，基极电流由哪些分量组成？',
     controls:['vbe','vce','tau'],measure:'基区少子与能带',heading:'扩散把少子送到集电结边缘',
     eq:I('E')+'<mo>+</mo>'+I('B')+'<mo>+</mo>'+I('C')+'<mo>=</mo><mn>0</mn>',
     text:'在正向放大区，NPN 的电子从发射区注入，沿浓度梯度穿过中性基区，再由集电结电场扫入集电区。基区复合、从基区反向注入外侧区域、结区复合共同形成基极电流。三个端口均以流入器件为正。',
     limit:'中性基区解稳态少子扩散方程，边界浓度由两结偏压决定。箭头表示分量方向，幅值以电流读数为准。'},
    {name:'四种工作区',title:'在偏置平面上切换工作区',q:'先将发射结正偏、集电结反偏，再保持发射结电压，向前推动集电结偏压。何时进入饱和？',
     controls:['vbe','vce'],measure:'可拖动的两结偏置平面',heading:'用两个结的偏置判断工作区',
     eq:V('BC')+'<mo>=</mo>'+V('BE')+'<mo>−</mo>'+V('CE'),
     text:'正向放大时发射结正偏、集电结反偏；两结同时正偏时进入饱和。两结反偏为截止，只有集电结正偏为反向放大。发射区与集电区掺杂不对称，因此调换注入端后电流增益也会改变。',
     limit:'区域按结电压的符号标出。极小的正偏已经改变分区，但实际电流可能仍然很小。反偏限于击穿前。'},
    {name:'电流增益的来源',title:'为什么窄基区能提高增益？',q:'保持电压不动，先加宽基区，再降低发射区掺杂。比较哪次主要改变输运因子，哪次主要改变发射效率。',
     controls:['width','tau','ne','vbe'],measure:'输运因子与基宽扫描',heading:'两个接近 1 的效率共同决定正向增益',
     eq:alpha+'<mo>=</mo><mi>γ</mi>'+sub('α','T')+'<mspace width="1.2em"/>'+sub('β','F')+'<mo>=</mo>'+frac(alpha,'<mn>1</mn><mo>−</mo>'+alpha),
     text:'γ 是发射端总注入中有效少子注入所占的比例。αT 描述这些少子穿过基区后到达另一侧的比例。加宽基区或缩短寿命会增加输运损失，降低发射极掺杂则会增强反向注入。',
     limit:'βF 为模型的正向输运增益。端口电流比还包含结区复合和反向结电流，尤其在小电流下会出现差异。'},
    {name:'Gummel 图',title:'从 Gummel 图测电流增益',q:'将游标 A、B 放在扩散主导区。集电极电流增加十倍需要多少毫伏？冻结曲线后改变温度。',
     controls:['vbe','temp','area'],measure:'Gummel 图 · 双游标提取',heading:'半对数斜率给出注入特征',
     eq:'<mfrac><mrow><mi>Δ</mi>'+V('BE')+'</mrow><mrow><mi>Δ</mi><msub><mi>log</mi><mn>10</mn></msub><mo>|</mo>'+I('C')+'<mo>|</mo></mrow></mfrac><mo>≈</mo>'+sub('V','T')+'<mi>ln</mi><mn>10</mn>',
     text:'将基极与集电极等电位，消去集电结的外加偏压。在室温的理想扩散区，约 60 mV 对应十倍电流变化。低电流时，结区复合会抬高基极电流并降低实测增益。',
     limit:'理想欧姆接触，未加入器件内部串联电阻与高注入增益衰减。高注入区域仅表示低注入模型的外推。'},
    {name:'输出特性与负载线',title:'让负载线选出工作点',q:'固定基极驱动，改变集电电阻。沿输出曲线读取局部输出电阻，观察集电结耗尽层进入基区的深度。',
     controls:['vcc','rc'],measure:'输出曲线族与电阻负载线',heading:'Early 效应来自中性基宽变化',
     eq:I('C')+'<mo>=</mo>'+frac(V('CC')+'<mo>−</mo>'+V('CE'),sub('R','C')),
     text:'提高集电结反偏会缩窄中性基区。固定发射结电压时，基区浓度梯度随之增大，输出曲线出现斜率。黑点是外部负载线与所选驱动曲线的交点。',
     limit:'负载线公式按 NPN 接法书写。PNP 电源及端口电流取相反极性。发射极接地，忽略器件内部接触电阻。'},
    {name:'共射放大器',title:'从静态工作点到电压放大',q:'先用小振幅比较两条输出波形，再增大输入幅度。波形向哪一侧先出现压缩？',
     controls:['vbias','amp','re','rl','rs','rc','vcc'],measure:'输入、非线性输出与小信号预测',heading:'小信号参数是工作点处的偏导数',
     eq:sub('g','m')+'<mo>=</mo>'+frac('<mi>∂</mi>'+I('C'),'<mi>∂</mi>'+V('BE')),
     text:'先由基极源电阻、发射极电阻和集电极电阻求直流偏置，再围绕该点施加正弦信号。大振幅下，输出会接近截止或饱和。发射极负反馈通常以降低增益换取更宽的线性范围。',
     limit:'1 kHz 准静态非线性传输。交流耦合电容视为足够大，发射极电阻无旁路。切换第 9 节可测频率响应。'},
    {name:'饱和与关断',title:'深饱和要付出多少关断时间？',q:'固定负载，逐渐加大正向基极脉冲。对比导通末端的 VCE 与关断存储时间，再提高反向抽取电流。',
     controls:['drive','reverse','pulse','rc','vcc'],measure:'开关波形 · 双游标与电荷积分',heading:'基极驱动先改变器件内的存储电荷',
     eq:frac('<mi>d</mi><mi>Q</mi>','<mi>d</mi><mi>t</mi>')+'<mo>=</mo>'+I('B,驱动')+'<mo>−</mo>'+I('B,稳态'),
     text:'负载限制集电极电流后，继续加大基极驱动可使两个结都正偏，过剩电荷进一步积累。撤去正向驱动后，复合与反向抽取共同清除这些电荷。双游标积分的是外部抽取电荷。',
     limit:'沿电阻负载线求解单状态集总电荷控制模型。忽略封装电感、热效应和结电容位移电流。正向与反向输运时间分开处理；存储电荷归零时结束反向驱动。'},
    {name:'高频与米勒效应',title:'器件的 fT 与放大器带宽',q:'在两种交流测试接法间切换，增大集电结电容或信号源电阻。哪个改动会影响器件的短路电流增益？',
     controls:['cmu','rs','rl','re','rc','vbias','vcc'],measure:'交流增益与带宽',heading:'反馈电容把输出变化耦合回基极',
     eq:sub('C','in')+'<mo>≈</mo>'+sub('C','π')+'<mo>+</mo>'+sub('C','μ')+'<mo>(</mo><mn>1</mn><mo>−</mo>'+sub('A','bc')+'<mo>)</mo>',
     text:'这里 Abc 是基极到集电极的电压增益。共射级反相时，跨接基极和集电极的电容会增大输入端的等效电容。测试 fT 时集电极交流短路；测带宽时保留源阻抗和外部负载。',
     limit:'在正向放大工作点使用混合 π 小信号模型。结电容随偏压变化，扩散电容来自储荷微分。忽略分布基区电阻、封装寄生及高阶输运。未形成有效交点时显示空读数。'}
  ];
})();
